quests[33463] = { id = 33463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Tide", description = "The majority of Karabor's defensive troops are dealing with the main battle front, just west of here. We must not ignore our flanks while dealing with that assault.\n\nOne of the enemy leaders, Arnokk, is directing the mayhem on this side of the temple. Take him out, along with as many of his orcish followers as you can stomach.\n\nOnce you've finished, meet me in front of the temple.", objectives = "Slay Arnokk the Burner and 10 Iron Horde troops within Karabor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33464] = { id = 33464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Over the Walls", description = "Karabor is falling. The Iron Horde will not stop this assault until every last one of us is dead and cold on the ground.\n\nI don't know about you, but I don't plan on letting that happen.\n\nNow, there must be something we can do to prevent them from scaling the walls...", objectives = "Dislodge 6 Blackrock Grappling Hooks near Karabor's outer walls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33466] = { id = 33466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Artificers", description = "I have several lieutenants out there on the battlefield, doing what they can to hold this temple together. I need all of them, but first and foremost, I need my artificers.\n\nThe artificers are masters of technology and artifacts. If any one of my followers can understand the mechanics of those siege engines, it would be them.\n\nRommul is their leader. Send him to me.", objectives = "Convince Rommul to return to Velen near Karabor's western entrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33467] = { id = 33467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of the Warlord", description = "You've managed to survive this long, stranger. All that remains to be done here is to fell the Warlord of the arena.\n\nThis will be your first true test here. Bult would provide a challenge to even a battle-hardened Frostwolf.\n\nPlace the heads you've collected on spikes in the Frostfire Arena. They are sure to enrage the warlord and lure him into battle.\n\nCome out of the arena victorious and it will show that Durotan's trust in you was not misplaced.", progress = "Yes, traveler?", completion = "Impressive work.", objectives = "Kill Warlord Bult.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33468] = { id = 33468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Wolf Home", description = "Cowardly Thunderlords...\n\nDuring the battle for the citadel, runners informed me that the Iron Wolf is striking at our home. He'll find no easy footing there, Draka will make them pay tenfold for any of ours that they slay, but we must return quickly and chase the mongrels off.\n\nYou and your forces have proven valuable allies of the Frostwolves. We'd welcome your aid in securing our Wor'gol.\n\nI'll see you on the battlefield if you choose to come.", progress = "There are more Thunderlord to be killed.", completion = "Durotan's trust in you is well-placed, {name}. You have mine as well.", objectives = "Save Wor'gol from the Thunderlord clan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33469] = { id = 33469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farseer", description = "The Thunderlord warleader... {name}, you have to stop him.\n\nHe went to attack Drek'Thar at the Pool of Visions to the northwest!", progress = "Wolf Home will not be safe until this coward is dead!", completion = "Wolf Home is saved, but I sense a stronger enemy just over the horizon.", objectives = "Get to the Pool of Visions and kill Warleader Gargrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33470] = { id = 33470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Visions", description = "A terrible storm gathers on the horizon, {class}.\n\nI have prepared a ritual. You must consult the pool to see what destiny holds for us all.", completion = "This Iron Tide threatens to sweep over all of Draenor.\n\nThe pool has shown you a possible future. This vision of the Frostwolf clan's destruction must not be allowed to come to pass.\n\nYou must stop it, {name}.", objectives = "Speak with Farseer Drek'Thar at the Pool of Visions to begin the ritual of vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33473] = { id = 33473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Bladespire Citadel", description = "Durotan must be told of your vision. Pul Windcarver will offer you a flight back.\n\nThe fate of the Frostwolf... of Draenor, depends upon you, {name}.", completion = "Grim news indeed, {name}.\n\nFor saving Wolf Home, I would name you wolf-brother.\n\nNow we must defend Frostfire Ridge from the Thunderlord clan and the Iron Horde.", objectives = "Return to Durotan at Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33483] = { id = 33483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mulverick's Plight", description = "You were sent here to free me? It seems that makes us allies.\n\nSlavemaster Turgall within the Soostained Mines will certainly have the key to this cage.\n\nWhile you're in there, do you think you could see which of those spineless taskmasters took my axes?", progress = "These ogres will be seeing the other side of my axes soon.", completion = "You have my sincere gratitude, {name}.", objectives = "Get the key from Slavemaster Turgall and find Mulverick's Axes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33484] = { id = 33484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slavemaster's Demise", description = "Share word with the others of the Frostwolves you saved this day. They will be glad to know that some made it out of the mines alive.", completion = "You found Mulverick?\n\nIt shouldn't be long before those ogres clear out after you defeated their master.", objectives = "Speak to Guse at Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33485] = { id = 33485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiplayer Race", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nGet to the purple marker\nReturn here...\nThen do it all again. That's right - 2 laps!\n\nGood luck!", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33492] = { id = 33492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northshire Sprint Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here.\n\nYou have all the time you need for this.", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33493] = { id = 33493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Pack", description = "Part of me agrees with Karg - we COULD challenge the Iron Wolf right now. My fists clench at the mention of his name. My muscles scream for vengeance.\n\nBut then, in my heart, I feel Asha. Calming me. Guiding me. I do not deserve her wisdom, but it is a gift I will not waste.\n\n<Lokra squints at the sky.>\n\nDurotan and the others will be gathering at your garrison about now. We should meet them.", completion = "Lokra has always lacked the patience and control of her older sister. She approaches problems head-first, and relies on her raw talents to succeed.\n\nSeeing the way her and Karg look at each other, I am not surprised she chased him all the way to Grom'gar. What surprises me is that they made it back.\n\nAs usual, I expect we have you to thank for that. You continue to honor us with your deeds.", objectives = "Speak with Durotan at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33496] = { id = 33496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde in Karabor" }
quests[33497] = { id = 33497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Time-Warped Brute Falling 2" }
quests[33498] = { id = 33498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Bladespire Chef" }
quests[33499] = { id = 33499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Time-Warped Ogre" }
quests[33500] = { id = 33500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Slave's Stash" }
quests[33501] = { id = 33501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Arena Spectator" }
quests[33502] = { id = 33502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Carved Obsidian Idol" }
quests[33504] = { id = 33504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shaman Fire Stone" }
quests[33505] = { id = 33505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Wiggling Chimaera Egg" }
quests[33509] = { id = 33509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Assault", description = "Thank the Light you're here. The Bonechewer orcs have invaded!\n\nWe've dealt with the occasional raid before, but they've never attacked Auchindoun with such numbers before.\n\nWe arrived as quickly as we could to respond to the threat, but the local guard had already fallen. We cannot afford to lose more men!\n\nKill all of the Bonechewer you can and help consolidate our forces back to our defensive line. The Bonechewer must not be allowed to step foot in Auchindoun!" }
quests[33510] = { id = 33510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Assault", description = "My scouts have reported that the Bonechewer clan is attacking Auchindoun, {name}. The Auchenai guard are here, but I fear they won't be enough.\n\nI sense a dark presence nearby... we cannot chance leaving their defenses weak. Too much power lies within those hallowed halls.\n\nSlay the Bonechewer and direct any of the Auchenai injured back to their defensive line. I will direct my scouts throughout the area to try to ascertain the Bonechewers' motives." }
quests[33511] = { id = 33511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sacrifice Pit" }
quests[33512] = { id = 33512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Lava-Gorged Goren" }
quests[33513] = { id = 33513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackthorn's Lieutenants", description = "Amnennar's reincarnation is imminent. In order to protect the ceremony Death Speaker Blackthorn has placed his most trusted lieutenants between us and him.\n\nAarux, a plagued spider nests near his young, tended to by the Death's Head Aranomancers. Mordresh rallies Amnennar's forces upon the Bone Pile. Finally, Mushlump stands guarding the entrance to the Spiral of Thorns.\n\nOnce you defeat these guardians I will join you and together we will confront Blackthorn.", progress = "Have you cleared the way?", completion = "You have done well, but this is only half of the battle. With his support structure in disarray it is time to strike at Death Speaker Blackthorn.", objectives = "Kill Aarux, Mordresh, and Mushlump.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33514] = { id = 33514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual", description = "You are good to have come so quickly.  I must ask you to put your lives in danger once more in order to save Kalimdor.\n\nAmnennar's apprentice, Death Speaker Blackthorn, hopes to return his master to the realm of the living!  We must quickly make our way atop the Spiral of Thorns and defeat him before the ritual can be completed.  We must strike together, only with our combined force can we hope to stop him!", progress = "Quickly {name}, you must stop the ritual!  Amnennar cannot be allowed to return.", completion = "A job well done, {name}. With Amnennar's phylactery now protected by the Red dragonflight we can now rest at ease.", objectives = "Kill Amnennar the Coldbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33516] = { id = 33516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Safety First", description = "These plans were designed to be read by even the most unskilled of metallurgists. It has big symbols on specific pipes for what valves NOT to turn unless risking woeful amounts of destruction.", objectives = "Disable 4 Safety Valves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33521] = { id = 33521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Auchenai Caretakers", description = "I was fortunate enough to be delivering a report to the Exarch when the demons attacked, but the rest of my brethren were out tending to the Court of Lights!\n\nWe caretakers are not the fighters of our order. Go to the court northwest of here and help direct them to safety.", objectives = "Direct 6 Auchenai Caretakers to safety in the Court of Lights in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33522] = { id = 33522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felblood", description = "Fascinating. The doomguard in the courtyard southwest of here have disguised themselves as orcs and do not die when defeated in battle.\n\nYou see, they are powerful magical beings, and their essence manifests nearby as a blood creature that revives its body upon reaching it.\n\nI would like to study these essences without dealing with the demons myself. Bring me a few samples, would you?", objectives = "Collect 6 Felblood Samples by killing Stormreaver Fearmongers in the Court of Lights in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33525] = { id = 33525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Orc Couple" }
quests[33526] = { id = 33526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Colors Don't Run", description = "Bladespire has been a plague on my people for many years.\n\nThat ends today!\n\nNow to explain it to the ogres in a way they will understand.\n\nIf you still wish to help us, place our banner in the corpses of our adversaries. \n\nTheir courage will falter as they behold a field of Frostwolf trophies!\n\nThis is our way. I will meet with you ahead when you have completed this deed.", progress = "Yes?", completion = "These are no ordinary enemies, yet you did not show any signs of weakness.", objectives = "Use 8 Frostwolf Banners on Bladespire Ogre corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33527] = { id = 33527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Steps", description = "In a rage, Ga'nar ascended to fight Gorr'thog, the ogre king.\n\nHe is alone, and the ramp to the throne room is now blocked.\n\nYou've proven resourceful. Perhaps you could find another way up?\n\nI sustained wounds on my way here, but I will work to cut my way through and up the ramp so we may rejoin.\n\nHurry traveler, ensure that the Frostwolf clan wins our assault on the citadel.", completion = "We called you outsider, {race}, but you have shown the strength and heart of a Frostwolf.", objectives = "Climb the chain and kill Gorr'thog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33529] = { id = 33529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare in the Tomb", description = "In the tomb... horrible... bodies everywhere...\n\nA dark ritual... please... you must stop it...", objectives = "Investigate the ritual in the Tomb of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33530] = { id = 33530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare in the Tomb", description = "Down there... horrible... bodies everywhere...\n\nDark ritual... please... you must stop it...", completion = "If this Teron'gor gains control of Auchindoun, the results would be catastrophic!\n\nWe must stop him before his power grows!", objectives = "Investigate the ritual in the Tomb of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33531] = { id = 33531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Fallen Ogre" }
quests[33532] = { id = 33532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ogre Cache" }
quests[33533] = { id = 33533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Gorgrond", description = "Our victory today was costly. Too costly. There is no guarantee that we can turn another attack.\n\nWe need to know what the Iron Horde is up to, and there is only one place we can go to find out.\n\nGorgrond.\n\nIt is a savage land that few ever return from.\n\nI mean to go there, I mean to find their stronghold at Blackrock, and I mean to learn how we can defeat these vile orcs.\n\nWill you join me, Commander?", completion = "Welcome to Gorgrond, Commander. We only just arrived ourselves.", objectives = "Seek Yrel at the Wildwood Wash in Gorgrond. Speak with your Garrison Gryphon Master to fly there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33534] = { id = 33534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find D'kaan", description = "D'kaan's nearby. He said something about unusual tracks. Hardly what we need to be focusing on at a time like this.\n\nWe need to leave soon. Help him, would you?", sourceObjective = "Find Rangari D'kaan at Tailthrasher Basin in Gorgrond.", sourceObjectiveStatus = "unverified-source-field" }
quests[33536] = { id = 33536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Element of Demise", description = "The Frostwolves are a fierce and noble clan, but distrustful of outsiders.\n\nWe have arrived amidst their assault on a mighty ogre citadel. I will remain here to offer counsel to their chieftain, Durotan.\n\nYou are a proven hero of Azeroth, {name}. Demonstrate your value to the Frostwolves. We need them as allies.\n\nUse my totem to thwart the ogre counterattack. This should serve to get their attention.\n\nThe rest is up to you.", objectives = "Place Thrall's totem at the center of the bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33540] = { id = 33540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Uzko's Knickknacks" }
quests[33543] = { id = 33543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Laughing Skull", completion = "Ha! Curious. What are you?", objectives = "Find a Laughing Skull clansman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33544] = { id = 33544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren, Goren, Gone!", description = "We... we left the goren alone for too long. They have grown bold and forgotten who we are.\n\nKill them! Kill them all. Rip them apart until they scream. Remind them what happens to anyone who tries to attack a Laughing Skull village.\n\nOh, and welcome to Gorgrond.", completion = "Ripfist's dying wish has been satisfied. Goren corpses litter the ground, and these corpses have not gone unnoticed by the nearby goren.", objectives = "Slay 8 Acidtooth Devourers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33545] = { id = 33545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkonite Crystals", description = "Mage-Lord Bloodsworn and I recently completed the first of our new blood golems. Once we're in full production, we won't need to risk lives in the field!Unfortunately, they still need a core power crystal.\n\nWe spotted a Draenei mine overrun with crystal-hungry Goren nearby. Do what you must to get enough crystals to power our golems!", objectives = "Gather 8 Arkonite Crystals at the Overload Mine in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33546] = { id = 33546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeds Left Undone", description = "In his haste, Ga'nar advanced before this area was secured. He is a matchless warrior, mind you, but his tactics are sometimes costly.\n\nGol'kosh and his troops were ordered to destroy enemy supplies, but ogres have stolen the oil he needs.\n\nRetrieve the oil and see that their mission is carried out, traveler. Then, if they still live, direct them to rejoin me at the citadel's entrance.\n\nI must see my wounded brothers to safety.", progress = "Lok'tar, traveler.", completion = "Gol'kosh has completed his mission, then.", objectives = "Collect barrels of Frostwolf Oil and deliver it to Gol'kosh in the supply room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33547] = { id = 33547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Times", description = "I have heard of the orcs you saw in the tomb before... this is not good news.\n\nIf they seek the key to Auchindoun, we must stop them from obtaining the remaining key fragments. Nyami was right; the fragments are no longer safe where they lay.\n\nThere's no time to waste. We will ride together to the Tomb of Lights and secure them ourselves.", objectives = "Ride to the Tomb of Lights with Exarch Maladaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33548] = { id = 33548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Die Laughing!", description = "Are you here to help or hinder?\n\nThis village is being eaten, and we must move quickly to salvage what we can.\n\nGather the masks of our fallen Laughing Skull brothers and sisters and meet me on the western side of the village.\n\nI will need them if our clan is to rebuild.", progress = "We are the Laughing Skull! We do not flinch in the face of death. We laugh at it.", completion = "These are more than fancy facewear. With a mask and some proper incentive, we can make anyone a Laughing Skull.", objectives = "Collect 5 Laughing Skull Masks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33549] = { id = 33549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of Chaos", description = "Durotan had a plan.\n\nThere were many paths to victory, but his was the most wise. His would cost the least blood.\n\nHis brother, Ga'nar, is one of our most revered warriors, but he is prone to give in to blood lust. As the first Frostwolf fell, his temper won over his discipline. He ordered the bulk of our forces headlong into the citadel.\n\nThis is not the first time Durotan's brother has abandoned reason, but it may be the most costly.\n\nFind them, stranger. Do what you can to salvage our assault.", sourceObjective = "Find Lorgosh in Bladespire Citadel", sourceObjectiveStatus = "unverified-source-field" }
quests[33557] = { id = 33557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddy Waters", description = "<Cough>\n\nNot feeling so strong... dehydrated...\n\n<Cough>\n\nNeed nutrients for leaves... need revenge...", objectives = "Find nutritious mud in the Spinebloom Spires to revive Jagahari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33560] = { id = 33560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Rest", description = "This map you found seems to show the locations of the other portals. By the Light, they have it surrounded!\n\nWe have a small staging area not far from the nearest portal. Let's go.\n\nNYI. Cheat this quest and go to the camp.", objectives = "Ride with Exarch Maladaar to Light's Rest in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33561] = { id = 33561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Multiplayer Race", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nGet to the purple marker\nReturn here...\nThen do it all again. That's right - 2 laps!\n\nGood luck!", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33562] = { id = 33562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy: Gorg'ak's Obsidian Spines" }
quests[33563] = { id = 33563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Candy", description = "You! Get in the fight or get out of our way.\n\nThis is no ordinary goren attack. Look over there, a gronnling is sacking our grubhall. That hunchbacked gorebucket bit a chunk out of my lovely Marrow!\n\nRip the eye out of its forehead and bring it to me.\n\nThat should buy me enough time to get her clear of this goren hole.", progress = "Did you make that thing scream? Did it beg for mercy? Did you kill it before taking its eye? Tell me everything.", completion = "These puppets of the magnaron will pay for the skulls they claimed today.\n\nFor now, I shall wear this eye across my waist so this fool you have slain may watch as I slowly slaughter his brethren until my dying breath.", objectives = "Collect Skothwa's Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33564] = { id = 33564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hanging Satchel" }
quests[33565] = { id = 33565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Chimaera Scale" }
quests[33566] = { id = 33566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Waterlogged Chest" }
quests[33567] = { id = 33567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shaz'gul" }
quests[33568] = { id = 33568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Kaliri Egg" }
quests[33569] = { id = 33569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Carved Elekk Horn" }
quests[33570] = { id = 33570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Exile Treasure" }
quests[33571] = { id = 33571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Clan Treasure" }
quests[33572] = { id = 33572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Pale Cave" }
quests[33573] = { id = 33573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Rovo's Dagger" }
quests[33574] = { id = 33574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Vindicator's Cache" }
quests[33575] = { id = 33575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Demonic Cache" }
quests[33577] = { id = 33577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Threat", description = "Aruuna, a draenei mining settlement to the northeast, has been sacked. Strangely, it doesn't sound like the work of the Iron Horde.\n\nMy scouts describe the attackers as \"giant fire-breathing birdmen.\"\n\nI suppose nothing in this place should surprise me anymore...\n\n<QUESTGIVER points to her map.>\n\nRefugees have been seen fleeing along this road. Help them if possible, and learn whatever you can about the attackers.\n\nif these \"birdmen\" are a threat, we need to know.", sourceObjective = "Speak with Crystal-Shaper Barum at the crossroads northwest of Aruuna.", sourceObjectiveStatus = "unverified-source-field" }
quests[33578] = { id = 33578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrophobia", description = "W- we have done n-n-nothing to provoke the arakkoa... w-why would they attack Aruuna? What do they want from us?\n\nI want to run, but I'm... too afraid. That leader of theirs will burn me to a crisp, I just know it!\n\nH-he's just inside the inn...", progress = "SHH! K-k-keep your voice down... they'll find us!", completion = "You killed him? Oh, oh thank you!\n\nBut what was that he said about an artifact?", objectives = "Slay Sun-Sage Kairyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33579] = { id = 33579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Draenei Found", description = "They came here for an artifact? The miners must have found something in our crystal mine to the north.\n\nBy the Light, can you imagine how powerful that thing must be, to attract them all the way here from their spires?\n\nI suppose it is in their hands now... You'd have to be crazy to go looking for it...", completion = "I was worried my little act wouldn't fool you, but you played your role perfectly.\n\nIn fact, I would like to ask for your help again.", objectives = "Examine the Ancient Prism in the Aruuna Crystal Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33580] = { id = 33580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purge of Veil Shadar", description = "Not all arakkoa are alike.\n\n<Iskar lifts his sleeve to reveal a mangled, useless wing.>\n\nIt is no illusion. They did this to me. Before I was even given a name, I was given a place in society: at the bottom.\n\nWe are many. We make our homes in the places this world has forgotten.\n\nVeil Shadar was such a place, but the Adherents have found it and started a purge. For morale. For fun.\n\nHelp my people escape, and we'll be in your debt.\n\nWhen the sky burns, it pays to have allies in the shadows.", completion = "Mark my words, {race}: Aruuna and Veil Shadar were only the beginning.", objectives = "Help 8 Arakkoa Outcasts evacuate from Veil Shadar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33581] = { id = 33581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Knowledge", description = "<Darkscryer Raastok narrows his eyes and looks you up and down.>\n\nSo, you are Iskar's hired hand? Well, I care not whether you are |5{race} or an overgrown moth, so long as you are willing to help.\n\nThe Adherents of Rukhmar are closed-minded fools! They forbid the study of shadow magic, branding as heretics anyone who dares to seek answers in the dark.\n\nWe kept many tomes of forbidden knowledge in Veil Shadar. Bring any you find to me, and I will reward you for keeping them from the flames.", progress = "What kind of sick individual burns a book full of perfectly good dark arts?!", completion = "Yes, yes. Excellent work, these are some of my favorites.\n\nKnowledge is power, and now I can leave for the spires feeling well-armed.", objectives = "Recover 6 Shadow Tomes from Veil Shadar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33582] = { id = 33582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kura's Vengeance", description = "I was a wing-guard myself, once upon a time.\n\nOne afternoon, I was caught away from my post. I just wanted an hour to watch the festival... Kuuan was supposed to cover for me, but instead he sold me out to gain favor with our superiors.\n\nThey plucked my eyes, broke my wings, and threw me off the spire.\n\nYet I am the fortunate one, for if Iskar hadn't found me, I'd have died there. And now Kuuan shows his face in Veil Shadar on the same day that you show up willing to kill for coin. Fortunate, indeed.", completion = "Speaking of fortune, count yourself lucky that I was not among the defenders in Aruuna, for you'd have seen both ends of your guts before you laid eyes on the Fire-Sage.\n\nAh, sometimes I miss those days.\n\nHere is your coin.", objectives = "Slay Wing-Guard Kuuan in Veil Shadar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33584] = { id = 33584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ashes of A'kumbo" }
quests[33586] = { id = 33586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Shadows", description = "Not all of the Shadowmoon orcs followed Ner'zhul's alliance with the Iron Horde.\n\nAmong them, there is one orc whom I befriended many years ago. She may be able to tell us more about Ner'zhul's plans for this \"Dark Star.\"\n\nShe can be found at Exile's Rise to the northeast. I will send word ahead so she expects your arrival.", completion = "I felt that this day would come. The draenei prophet is not wrong to seek me, traveler.\n\nThough we do not speak often, he and I have a deep mutual respect for one another.\n\nI know the trouble that his people are suffering, and I no longer believe the Shadowmoon are following our ancestor's path.\n\nFor those reasons, I will help you.", objectives = "Speak to Rulkan at Exile's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33588] = { id = 33588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Break Corrupt Deathweb Eggs" }
quests[33593] = { id = 33593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flare for the Dramatic", progress = "Hey there, commander!", completion = "That didn't seem to do much, commander, except to give away our position to every creature in Gorgrond.\n\nWait, did you hear something?", objectives = "Shoot Penny's Flare Gun while in Deadgrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33597] = { id = 33597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - The Obliterator" }
