quests[33614] = { id = 33614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Greka's Urn" }
quests[33622] = { id = 33622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Slaughter", description = "This entrance to the fortress is clear again, thanks to your help.\n\nInside is another story. Find your way inside and leave no ogre standing as you go.", progress = "Yes?", completion = "Again we meet...", objectives = "Kill 10 ogres in Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33633] = { id = 33633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rooter the Ravenous", description = "The stray boar is digging through garbage left behind by the iron horde. He stops chewing and stares at you-then he burps.\n\nHe smells terrible.\n\nIt looks like he's chewing on a chunk of rotten meat. Maybe you can find something a bit healthier for him to snack on?", progress = "That rotten meat looks gross. Find rooter something healthy to eat.", completion = "You feed the hungry boar the nopales. He devours them whole and smacks his lips.\n\nRooter jumps up onto you and licks your face with his disgusting tongue.\n\nIt looks like you have made a new friend.", objectives = "Find food for Rooter at Rooter's Pass in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33635] = { id = 33635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Seen Gazebo Explosion" }
quests[33638] = { id = 33638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insatiable Swarms", description = "Something has spurred the podlings that live in the nearby forest to come here. They are scaring the talbuk, eating the crops, and slaughtering my people!\n\nI led refugees from Tuurem here in search of safety from the Iron Horde, and now we have to contend with these foul creatures!\n\nPlease, you must help us! I need to attend to my wife's wounds and guide her to safety. Meet me inside the farm proper towards the back when their numbers have been culled back.", objectives = "Kill 20 Podlings at Kuuros Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33640] = { id = 33640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Veloss" }
quests[33641] = { id = 33641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hippo Boss" }
quests[33642] = { id = 33642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mother Om'ra" }
quests[33643] = { id = 33643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Venomshade (Plant Hydra)" }
