quests[33645] = { id = 33645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Iskar's Hired Hand" }
quests[33649] = { id = 33649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Torched Iron Horde Scout" }
quests[33656] = { id = 33656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Roundup", description = "My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped!\n\nThe little terrors could have slaughtered them in the cage, but they like to hunt their prey. I'm afraid that if I stay out here much longer, I'll be their next meal!\n\nWill you round up the talbuk and bring them here? I can't get them myself, and I can't let my dad find out about this!", objectives = "Rescue 4 Talbuk at Kuuros Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33657] = { id = 33657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving In", description = "Gorr'thog is now dead. It is time now to secure our hold on Bladespire Citadel. Meet me below and we can begin strengthening our presence.", completion = "You have accomplished great things. We could not have captured this citadel without you.", objectives = "Meet Durotan at Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33658] = { id = 33658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Missive", description = "<The missive outlines a plan to pollute Elekk Acres to ruin the Draenei food supply while their leader, Thokk, sends a force from a camp on the hill to the northwest to slaughter the remaining refugees.>\n\n<If you burn their supplies here and their forward camp with the torches they left here, you can buy precious time to organize a defense against the imminent attack!>", objectives = "Burn the Iron Horde Supplies and the Iron Horde Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33659] = { id = 33659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Put Down Poisoned Elekk" }
quests[33660] = { id = 33660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacking of the Saberon", description = "The stash mostly contains bits of old animal parts and other junk. Upon closer inspection there are remains of a bundle of herbs and plants.\n\nRakthoth might be more willing to help if some of these herb bundles were found and gathered for her...", progress = "I need more reagents before I return to my brothers and sisters.", completion = "So they started storing their herbs in personal stashes instead of their storage dens, good to know.\n\nYou have helped me a great deal {name}.", objectives = "Find 8 Herb Bundles in saberon stashes at Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33661] = { id = 33661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steamscar \"Reagents\"", description = "Now we get to the heart of the matter, heh. Saberon have strong hearts, our shaman find many uses for them.\n\nI will search for the ancient's magic if you get me those hearts. Do we have a deal?", progress = "I will need those hearts {class}.", completion = "These are good strong hearts! You have done well {class} and I will hold my end of the bargain.", objectives = "Collect 10 saberon hearts from living saberon at Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33662] = { id = 33662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beatface vs. Boulder", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a boulder, but it looks weak. A strong warrior, such as an ogre, could break it.\n\nI think you know an ogre gladiator...", completion = "Good work, but we need to move quickly before the plants realize the way is open...", objectives = "Break the boulder barrier using Beatface the gladiator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33663] = { id = 33663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder vs. Saberon", description = "After the saberon stole from these plants, they were forced further up Steamscar Rise and barricaded themselves in. I could not find a way to get in but you have the solution.\n\nOne path is blocked by a tangle of hard vines. I have heard you have a machine that could cut through that with ease.\n\nI would get on a shredder and take those vines down.", completion = "Good work, but we need to move quickly before the plants realize the way is open...", objectives = "Break the vine barrier using your shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33664] = { id = 33664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gorum" }
quests[33684] = { id = 33684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", sourceObjective = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[33685] = { id = 33685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambassador to the Ancient", description = "I have seen a tough looking \"tree\" in that growth. It cries and moans but does not act hostile.\n\nIt may know how to get rid of these plants. Go and see if it does.", completion = "So that is why the saberon have barricaded themselves up there. They are good hunting {name}, and I want to get in there!\n\nI have an idea about that...", objectives = "Talk to Birchus at Dionor's Demise in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33686] = { id = 33686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's No Podling", description = "<This leaf appears to have come from a plant hydra. The refugee sightings Beldos mentioned must have been true!>\n\n<If one got to the farm, the draenei refugees would stand no chance. Killing it now would buy valuable time for the refugees to reach safety.>\n\n<It must still be at the nearby podling den to the west.>", objectives = "Slay Bloodthrasher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33689] = { id = 33689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plant Pruning", description = "I have a hunting den not far from here where I gather my trophies as well as reagents for the Laughing Skull. Not long ago this giant plant monster charged in from the overgrowth and was killed by several of the giant rock monsters. Since it died smaller plant beasts have sprung up and made a mess of the place.\n\nThey have also cut me off from my best source of reagents. Kill them, I will attempt to reach my den and salvage what I can...", progress = "Have you cleared a path yet?", completion = "They just keep coming back! I would hate to lose this hunting ground. We shall find a way to clear this growth, I swear it.", objectives = "Kill 12 defenders at Dionor's Demise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33693] = { id = 33693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: First Time at Capping Operation" }
quests[33694] = { id = 33694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents from Rakthoth", description = "The destruction of our village will not be easy to come back from. Our best hunter, Rakthoth, \"finds\" reagents for our shaman.\n\nShe has not been seen for some time and we need those more than ever. Go to her hunting grounds and see if she still lives.", completion = "Marrow sent you? Our village destroyed? I would have been back already if it wasn't for these cursed plant beasts!", objectives = "Find Rakthoth at Dionor's Demise in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33695] = { id = 33695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Death Bloom", progress = "Do you have something for me, little beast?", completion = "You have... you have brought me the bloom. At last my purpose can be fulfilled!", objectives = "Take the Death Bloom from Smokemaster Snarl in Steamscar Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33705] = { id = 33705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacking the Saberon Stronghold", description = "[TEMP]Destroy the barricade and take back stuff!", sourceObjective = "Breach the last saberon wall and deal with what's on the other side.", sourceObjectiveStatus = "unverified-source-field" }
quests[33706] = { id = 33706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", completion = "At last it is done.  Dionor has left and his spawn shall follow him in due time.\n\nI grow weary of this conflict and the desire to return to the Overgrowth has left me.\n\nPerhaps I will travel beyond these lands and see what other surprises you little beasts have to share...", objectives = "Watch Birchus's ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33707] = { id = 33707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Us - Horde", description = "If you are reading this, it means I have fallen in battle. As my last request, please deliver this letter to Thalia at Teluuna Observatory.\n\n\nDearest Thalia,\n\n\nYou have always been my best friend, ever since we were children growing up in Tuurem.\n\nI have always been too afraid to tell you my feelings, but I cannot leave this world without finally speaking the truth.\n\nThalia, I love you with all my heart.\n\nI shall wait for you in the next world. I will for eternity for you.\n\nLove,\n\n\nThamuun", sourceObjective = "Deliver Thamuun's Letter to Thalia at Teluuna Observatory.", sourceObjectiveStatus = "unverified-source-field" }
quests[33713] = { id = 33713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TASK: Kill Ogre Slavers", objectives = "Kill 12 Stonemaul ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33720] = { id = 33720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decommissioned Mission", description = "Ketya Shrediron,\n\nYour new Iron Shredders are a menace to our own soldiers.\n\nDecommission the prototype and store it in the cave on Talador beach until you've worked out the kinks.\n\nI will send Engineer Draxen to work on it in the meantime.\n\n- Orgrim Doomhammer", completion = "A prototype Iron Shredder, huh?! I bet we can get this thing working... they didn't have ME to fix it!", objectives = "Find the Decommissioned Iron Shredder in the nearby cave and take it from Engineer Draxen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33721] = { id = 33721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowe's Solution", description = "I've identified some high value targets down in the forest below.\n\nWhen you get near one, you can deploy my solution.\n\nDeploy it and the objectives will be neutralized with great ceremony.", completion = "I always love a good explosion.", objectives = "Destroy the Thunderlord Cache, Blackrock Forge, and Munitions Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33722] = { id = 33722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Many Irons in the Fire", description = "We must not head into battle prematurely. Before we go after Orgrim, we must first deal with his troops.\n\nIf we are to succeed in our mission of wiping out the Iron Horde from Talador, we need to start on these shores.", completion = "We will have fewer enemies to deal with at our backs. Lok'tar.", objectives = "Kill 15 Iron Horde on Orunai Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33724] = { id = 33724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vol. X Pages ?", description = "The manual for the shredder was wedged in there, but it's missing lots of pages. We need to find as many pages of that manual as possible and I might--MIGHT--be able to get this shredder operational.\n\nBased on the direction of the wind, I bet the pages flew toward Archenon Siegeyard.", progress = "I don't know why those idiots don't just collect all the pages in one place.", completion = "Lots of detail... almost as if a goblin wrote it!", objectives = "Find 20 Manual Pages at Archenon Siegeyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33726] = { id = 33726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuurem Task TBD" }
quests[33727] = { id = 33727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heal Up" }
quests[33728] = { id = 33728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eye for a Spy", description = "Excellent, excellent! I'll make sense of these manual pages and will get the Iron Shredder operational immediately!\n\nWhile I do that, take a look through my Eye 'n' Ear. That's where you'll be headed soon!", progress = "Lots of orcs ready to be shredded!", completion = "Orgrim seems to be up to no good.", objectives = "Look through Gazlowe's Eye 'n' Ear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33729] = { id = 33729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Born to Shred", description = "The Iron Shredder is operational! It should be primed and ready for you to shred our enemies in Tuurem!\n\nHead inside and see what damage you can do. Can't say I'm not jealous.", progress = "What's up, boss?", completion = "-- ENEMIES ELIMINATED --", objectives = "Kill 100 Iron Horde in Tuurem using the Iron Shredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33730] = { id = 33730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering Her Demise", description = "-- THE MOTHER HAS BEEN DETECTED. WARNING! WARNING! --", completion = "Gazlowe has been invaluable in securing Talador. Now, it is up to us.", objectives = "Defeat Ketya Shrediron at Tuurem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33731] = { id = 33731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Shattrath", description = "To stop the Iron Horde, we must overcome prejudice and work together, if only for this purpose.\n\nHorde, Alliance, past, present... all meaningless in the face of this enemy.\n\nWe will retake Shattrath together... or die trying.", completion = "I cannot believe Orgrim is truly dead. Blackhand has carved a hole in my heart, and I intend to destroy him when the opportunity presents itself.", objectives = "Repel the Iron Horde from Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33732] = { id = 33732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage Siege Weapons" }
quests[33733] = { id = 33733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karmaan", description = "You saw iron horde fighting the podlings!? That must be why the podlings are attacking here; they've been displaced!\n\nUnfortunately, they likely followed me and the other refugees from Tuurem to here. Light help me, I've doomed us all.\n\nWe should go tell Karmaan about this. If the iron horde is nearby, podlings might be the least of our problems.", sourceObjective = "Speak with Karmaan.", sourceObjectiveStatus = "unverified-source-field" }
quests[33734] = { id = 33734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of Us", description = "When the fires broke out, I took only my daughter's hand before we fled. It was the right decision, of course, but I do long for some of the things we left behind.\n\nI am an artificer, a shaper of crystals and gems. Without my tools I am just another refugee.\n\nOur town records are kept in a memory crystal in the main hall. With it, I can carry forward the knowledge and legacy of Aruuna.\n\nAlso, my daughter is terrified - it would be a great comfort for her to hold her favorite doll again.", progress = "These are more than mere objects. They are our livelihood, our past and future, our comfort.\n\nThey are pieces of us.", completion = "Thank you.", objectives = "Retrieve the Crystal-Shaper's Tools, Melani's Doll, and the Annals of Aruuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33735] = { id = 33735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Short Supply", description = "The enemy has explosive devices stored on the beach below. We must recover them so they are not used against us.\n\nReports indicate that crates of explosives are scattered along the shoreline.\n\nWhile you search, Durotan and I will carve deeper into Iron Horde territory.", progress = "Have you found the Iron Horde Explosives yet?", completion = "I believe we can use these at Archenon Siegeyard.", objectives = "Collect 6 Iron Horde Explosives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33736] = { id = 33736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Them Out", description = "The orcs themselves are not the only threat. We may have weakened them considerably, but they still have siege weapons of significant power.\n\nSabotage siege weapons you find with the explosives you collected from the beach.", completion = "It is a relief to know that their weapons of war cannot be used against us.", objectives = "Destroy 6 Iron Horde Siege Engines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33737] = { id = 33737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike While the Iron Is Hot" }
quests[33740] = { id = 33740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Sky", description = "It happened so fast. A white-hot flash of light ignited the nearby woods, followed by terrible winds that swept the flames across Aruuna.\n\nMoments later, arakkoa began descending through the smoke.\n\nI need to get Melani to the Pilgrim's Road. From there we can head for Anchorite's Sojourn and the protection of the vindicators. With the arakkoa roaming the area freely, I fear we'll be run down or worse: taken by the spreading wildfires.", completion = "Their deaths will not bring back Aruuna, but it does give me comfort to know that some among us can stand against them.", objectives = "Slay 12 Adherent Invaders in Aruuna and the Aruuna Crystal Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33746] = { id = 33746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "'kish Joins the Party", description = "The little guy sure does look happy. It's pretty clear he wants you to pet him. There is a spot right on the top of his head that isn't totally covered in rotten meat.", objectives = "Invite Rooter to join your party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33748] = { id = 33748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Saberon Servent Snip Scene" }
quests[33749] = { id = 33749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Reward Summary: Train Depot" }
quests[33750] = { id = 33750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest Reward Summary: Pipeworks" }
quests[33754] = { id = 33754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Looking Glass", description = "Your allies sent along a goblin, Gazlowe, to advise us against the Iron Horde. Thus far, he has proven a valuable asset.\n\nHe has a looking glass set up that can see a great distance and, he claims, even hear.\n\nUse this looking glass and report back what you've seen. I will stick to my standard spyglass.", progress = "Take a look through Gazlowe's Eye 'n' Ear.", completion = "Orgrim leads these orcs? Why has he pledged himself to the Iron Horde?", objectives = "Look through Gazlowe's Eye 'n' Ear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33755] = { id = 33755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Test Race: 2 Laps", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nThen do it all again. That's right - 2 laps!\n\nGood luck!", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33756] = { id = 33756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Keep Racing!", description = "Want to keep racing, huh? That's the spirit!\n\nSee if you can beat your best time! Get to the blue post, then green, then red, then back here. \n\nYour time matters, so do it fast!", progress = "You haven't hit all the markers. Hurry!", completion = "Good job, and nice time!", objectives = "Run through the Start Banner, hit the Blue Post, then the Green Post, then the Red Post, then return to the Start Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33761] = { id = 33761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barum's Notes", description = "<This hefty tome contains notes on the refining and shaping of Draenor's natural gems and crystals, including several full-page technical diagrams depicting complex cut patterns.\n\nThe most recent pages detail a series of cuts intended to aid the draenei vindicators in battle.>\n\n\"...honed to a fine edge, the material can expose weaknesses...\"\n\n\"when rounded and polished to such a degree, it wards off harmful...\"\n\n\"...this incredible discovery that a crystal can be attuned to the bearer's vitality!\"", progress = "Hm, what is that book you have there?", completion = "My notes! In the chaos, I completely forgot about them!\n\nThis is my life's work, {name}. I cannot thank you enough.", objectives = "Test the effects of a Honed Crystal, a Polished Crystal and a Harmonic Crystal in Aruuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33765] = { id = 33765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Enemies", description = "Your arrival should be cause for celebration, hero, but I fear our troubles are just beginning.\n\nWarlord Ner'zhul and his Shadowmoon clan have launched a surprise attack on a draenei settlement to the north.\n\nProphet Velen has gone to aid the wounded at Teluuna Observatory, but we need more defenders.\n\nI must go to assist the others. If you wish to help us, go to Arbor Glen and kill any Shadowmoon enemies that you see.", completion = "The forests are clear of Shadowmoon enemies? Good. I knew that you would not fail.", objectives = "Kill 8 Shadowmoon Voidmancers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33766] = { id = 33766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thing in the Cave", description = "The note reads as follows:\n\n\"It cannot be defeated. No matter how many troops we send at it, it seemingly cannot be destroyed.\n\n\"We have lost too many lives as it is. I refuse to send another orc after that thing. Instead, we will establish a guard station outside the cave's mouth to keep it from getting out.\"", objectives = "Slay the Thing in the Cave, then loot its Dreadful Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33767] = { id = 33767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thing in the Cave", description = "The note reads as follows:\n\n\"It cannot be defeated. No matter how many troops we send at it, it seemingly cannot be destroyed.\n\n\"We have lost too many lives as it is. I refuse to send another orc after that thing. Instead, we will establish a guard station outside the cave's mouth to keep it from getting out.\"", objectives = "Slay the Thing in the Cave, then loot its Dreadful Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33772] = { id = 33772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Invasion Opt-Out" }
quests[33781] = { id = 33781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Survivalist's Way", description = "I was tracking the Iron Horde's movements through the Iron March when I was spotted by one of their chimera riders.\n\nI was able to fight off their kill squad, but I'm too injured to keep going. Stranger, I must obtain as much recon as possible to aid in Karabor's defense.\n\nIf you can bring me silk from the worms and a handful of teeth from the rays at the lake nearby, I can operate on my wounds and fashion a bandage that ought to hold long enough for me to finish my mission.", objectives = "Collect 6 Glowworm Silk and 12 Razorfang Teeth in The Arbitum in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33782] = { id = 33782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Balance", description = "Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin.\n\nIt is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life.\n\nTrack down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.", objectives = "Kill Snapgrip in The Arbitum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33783] = { id = 33783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuuros Farm", description = "Many refugees from Tuurem have made their way to Kuuros Farm east of here.\n\nIf you are able, please venture there and find Beldos. He led the refugees there from Tuurem and will be the best point of contact.", sourceObjective = "Find Beldos at Kuuros Farm.", sourceObjectiveStatus = "unverified-source-field" }
quests[33784] = { id = 33784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormaul Tower", description = "It is time for us to strike out against those who would enslave us!\n\nWe travel to Gormaul Tower to wrest it from the Bladespire ogres. I would welcome your company.\n\nMount up, and together we will ride to battle!", progress = "You may ride with us and fight with our pack.", completion = "I now understand how you were able to rescue my clan from the clutches of slavery. Such power!", objectives = "Take Gormaul Tower from the Bladespire ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33785] = { id = 33785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karg Unchained", description = "They took my brothers and sisters.\n\nThey took my wolf.\n\n<Karg lifts his axe and fixes his gaze upon its edge.>\n\nNow we take their heads.", progress = "By killing them - we take their heads by killing them.\n\nWe don't actually need to pick up the heads.", completion = "<Karg scoops up a handful of snow and cleans the gore from his axe.>\n\nYou fight well.", objectives = "Slay 25 Thunderlord orcs in Grom'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33786] = { id = 33786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crippled Caravan", description = "I'm getting reports that the botani have started leaving their bloom and attacking wandering travelers. This is most unusual.\n\nWe already dispatched a number of rangari to try and resolve this issue.\n\nA caravan from Azeroth passed through here recently, you should probably check on your people to ensure their safety.", completion = "Commander! Am I glad to see you.\n\nWe have a situation here.", objectives = "Find Fiona's Caravan in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33787] = { id = 33787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona's Solution", description = "Gidwin was attacked by one of those plant creatures.\n\nFrom the looks of it, he is suffering from some kind of paralysis.\n\nI can make a cure, but I'll need some local ingredients.", progress = "Do you have the ingredients?", completion = "Bang-up job, {name}! The base is just about ready.", objectives = "Collect 1 Riverbeast Heart, 2 Swamplighter Venom, 4 Riotvine, and 3 Moonlit Herbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33788] = { id = 33788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking With Unstable Herbs", description = "The base is boiling and ready for those ingredients.\n\nAdd each of the ingredients, one at a time, and I will handle the mixing and frothing. Speak to me when you are ready.", progress = "Are you ready to begin?", completion = "Gidwin is looking much better. Thank you, {name}.\n\nWe have just enough elixir here to help the others.", objectives = "Help Fiona brew a curative elixir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33793] = { id = 33793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Void", description = "Our scouts have made a horrifying discovery, {name}.\n\nThe souls of the prisoners are being used to summon creatures from the void.\n\nInside, three beings of darkness already await - the Essence of Shadow, the Essence of Darkness, and the Essence of Anguish.\n\nThey must be destroyed immediately, before their power can be unleashed.", progress = "The souls of innocents were used to birth the foul creatures. All that is depraved, and sick, and twisted in this world, are embodied within them.", completion = "I knew I could trust this task to you, {name}.", objectives = "Destroy the Essence of Shadow, Essence of Darkness, and Essence of Anguish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33794] = { id = 33794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Salvation", description = "We've located the prisoners. They are being held in captivity here, inside the Shadowmoon fortress.\n\nPlease rescue as many of them as you can. And hurry. We can hear their screams out here.", completion = "We are taking care of the survivors now. We owe their lives to you. Thank you, {name}.", objectives = "Free 8 Draenei Prisoners from their cages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33795] = { id = 33795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Stars", description = "A key source of the Shadowmoon clan's power comes from their understanding of the stars and their omens.\n\nFor centuries, they have recorded the patterns of the stars and their interpretations.\n\nWhile you are in the fortress, collect some of these documents for me.\n\nWe will take their own knowledge and use it against them.", progress = "Your aid is appreciated, {class}.", completion = "Thank you. My acolytes will study these in great detail. With any luck, we will be able to use this knowledge to defeat the Shadowmoon.", objectives = "Collect 5 Star Readings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33800] = { id = 33800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darren's Bombing Run of Awesomeness" }
quests[33807] = { id = 33807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Our Brothers and Sisters", description = "These Thunderlord curs use coward's weapons like nets and chains.\n\nMany of our villagers and wolf-brothers and sisters have been trapped.\n\nIf you free them, they will fight at your side with honor.\n\nWe must quell this attack with haste so I may return to Bladespire Citadel and continue my preparations.", completion = "The Frostwolf clan cannot be held like beasts.\n\nYou fight with honor, {name}.", objectives = "Free 6 Frost Wolves or Wor'gol Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33808] = { id = 33808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamplighter Queen", description = "It looks like those plant creatures used some kind of poison when they attacked Gidwin.\n\nIt's a powerful concoction to say the least.\n\nIf we are going to cure Gidwin we need one more special ingredient. This one might be a bit harder to obtain than the others.\n\nYou up to the challenge, {name}?", progress = "I just wanted to pick some herbs and relax with my boys... I should have stayed in Azeroth.", completion = "Wow, that was fast! Ok, let's get to it!", objectives = "Obtain The Swamplighter Queen's Tail for Fiona in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33813] = { id = 33813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of a Hero", description = "I...<sob>... I can't leave...<gulp>... without... Squiggy...!\n\nHe... he's... trapped!\n\nYou need... to put out... the fire!\n\n<Ariaana points across the room and bursts into tears.>", progress = "Squiggy... is... my... best... friend!", completion = "You did it! Squiggy is okay!", objectives = "Save Squiggy by dousing fires with buckets of water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33814] = { id = 33814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fast Expansion", description = "Greetings, Commander.\n\nI am here on behalf of architect Baros Alexston.\n\nWe have gathered enough resources for the next phase of expansion.\n\nHe wishes to speak to you at your earliest convenience.", completion = "Ah, welcome, commander! Just the person I wished to see.", objectives = "Report to Baros Alexston at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33815] = { id = 33815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Song of Frost and Fire", description = "You have rescued many of my clan from the slave pens of Tanaan. Their liberation and the destruction of the Dark Portal are more than enough for me to consider you one of us.\n\nHowever, you are still a stranger to our leader, Durotan. I would like to introduce you to him.", progress = "What a strange creature you are.", completion = "I thank you for returning with my people, and I welcome you as an honored guest.", objectives = "Meet Durotan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33816] = { id = 33816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor Has Its Rewards", description = "You have honored my people. Now, we wish to honor you.\n\nWe have a rite of initiation in my clan. When one comes of age, they cover themselves in the blood of their first hunt, and rest their hands upon a shamanstone to honor the ancestors who came before them.\n\nIn our brief time together you have already slain many foes more fierce than our hunters have ever had to face. Go, touch the shamanstone here in Wor'gol, and join our pack as an equal.", progress = "Thank you for saving my clan.", completion = "If you choose to continue to help our clan, the other Shamanstones will sense your closeness to the Frostwolves and might bless you with more gifts.", objectives = "Go to the Shamanstone in Wor'gol and receive a blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33817] = { id = 33817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of a Struggle", description = "Judging by the markings, it appears to be a journal kept by a Shadowmoon orc.\n\n<Hagra disappeared last night. She is the fifth in as many nights. Why do they only vanish at night?>\n\n<I will find out. Tonight I wait for whatever manner of beast stalks our village.>\n\n<I will bring the beast's head to Rulkan, and return my kin to their homes.>\n\nPerhaps the beast's head is in one of the bags in the debris up ahead?", objectives = "Ruffle through the backpack near the bloody journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33820] = { id = 33820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Seen Escape Cinematic" }
quests[33822] = { id = 33822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laabru's Rebellion", description = "Laabru wouldn't listen. He killed one of the guards and they dragged him off to one of their tents.\n\nThey are going to kill him for sure!", sourceObjective = "Find Laabru at the Gar'mak Quarry in Shadowmoon Valley.", sourceObjectiveStatus = "unverified-source-field" }
quests[33823] = { id = 33823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #1" }
quests[33824] = { id = 33824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #2" }
quests[33825] = { id = 33825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Archaeology - Frostfire - Dig Map #3" }
quests[33826] = { id = 33826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's My Wolf?!", description = "My frost wolf, Nerok, was captured with me and the others. I do not know where they are keeping him, but I'll bet the so-called \"beastmaster\" who dragged us here does.\n\nHe is at the beast pens nearby, boasting about his catch to the younger hunters.\n\nWe'll see how he boasts with my axe in his skull.", progress = "I will not leave my frost wolf behind. Dead or alive, Nerok leaves this place with me.", completion = "Nerok and I are the only surviving prisoners, but we cannot leave just yet.", objectives = "Slay Beastmaster Torash and free Nerok in Grom'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33828] = { id = 33828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master Siegesmith", description = "Not long ago, the most advanced weapon a Thunderlord could make was a really, really big spear. The Blackrock orcs must have shipped in a fearsome master to have them producing cannons so rapidly.\n\nWe need to find that master.", progress = "Karg is right - this is our best opportunity to cripple Grom'gar's defenses. We do this, then we return to the clan, heads high with pride.", completion = "The Iron Horde combines the strengths of every clan. We must continue looking for ways to sever those connections if we hope to defeat them.", objectives = "Slay Master Siegesmith Uratok in Grom'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33829] = { id = 33829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLD Honor Has its Rewards" }
quests[33833] = { id = 33833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Kuu'rat's Tusks", description = "Posted by: Eremor\n\nA ferocious elekk of unprecedented size has been seen near Gloomshade Grove.\n\nKnown to some as the ivory death, she is abnormally aggressive and has already taken the lives of several unwary travelers.\n\nThe rangari have as yet been unable to corner this creature. Anyone capable of taking down this beast should exchange proof of her demise to Eremor for a hefty bounty.", progress = "Are you here for the bounty on Kuu'rat?", completion = "The ivory death is slain? Impressive, traveler.\n\nThanks to you, we are all safer with Kuu'rat gone. I will share news of this deed with the other villagers.", objectives = "Slay Kuu'rat and bring her tusks to Eremor at Embaari Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33834] = { id = 33834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Kliaa's Stinger", description = "Posted by: Dyuna\n\nA vicious queen swamplighter has made the northern forests of Shadowmoon its home.\n\nUnfortunately, this poisonous pest terrorizes the forest between Embaari Village and Shattrath. As local traders put their lives at risk, prices of goods will continue to rise.\n\nAnyone who can put an end to the beast should detach its stinger as proof and bring it to Dyuna in Embaari Village. The merchant traders will reward generously.", progress = "Word around town is you've been hunting Kliaa. Any luck?", completion = "By the elders of Karabor... that thing is huge!\n\nOur trade routes will be safe once again. Well... as safe as you can be running through the northern forests.\n\nWell done, {class}!", objectives = "Kill Kliaa and bring its stinger to Dyuna at Embaari Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33836] = { id = 33836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Maa'run's Hoof", description = "Posted by: Orrin\n\nA wild talbuk called \"Maa'run\" wanders the hills southeast of Embaari Village and west of The Draakorium.\n\nMy brother was injured by this foul beast, and now lays in recovery.\n\nFor the safety of all the nearby villages, we must put an end to this vicious, rampaging creature!\n\nA handsome reward will be given to anyone who can bring me his hoof as proof of his demise.", progress = "My brother, Anduur, gathers wild berries from the hills above our village.\n\nIt was during one of his excursions that he met up with Maa'run.\n\nI demand retribution for his injuries.", completion = "Thank you, adventurer! We can rest more easily knowing that this beast has been put to its end.", objectives = "Collect Maa'run's Hoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33837] = { id = 33837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Falls", description = "It is already beginning, over the hills to the southeast.\n\nNer'zhul has everything he needs to summon the Dark Star. The Iron Horde attack on Karabor is imminent. This is where everything ends.\n\nChampion, I must ask you to ride ahead and delay Ner'zhul. I will join you as quickly as I can.", progress = "Today is the day that everything ends. But something new rises from the ashes.", completion = "Prophet Velen is gone, and yet there is no time to mourn.\n\nWe will honor Velen's passing once the Iron Horde have fled from these hills.\n\nNow, champion, is the time to fight!", objectives = "Find Ner'zhul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33838] = { id = 33838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smeltcraft", description = "Stranger! Thank the spirits for them sending you to me now. I am forging a blade and cannot leave it at this delicate state.\n\nBut I need more ore to complete this task.\n\nHere, take my mining pick. It is crafted from the teeth and acid of the local goren and will cut through the ore of this area as if it were air.\n\nBring me the ore and I will lend this blade to your cause.", progress = "The power of a weapon comes both from the test of its metal and the skill of the hands that wield it.", completion = "Perfect timing. The steel of the blade is still malleable. A few more strikes and my work shall be complete.", objectives = "Use Na'Shra's Mining Pick to collect 20 Fomic Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33839] = { id = 33839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Naaru Purified" }
quests[33840] = { id = 33840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plight of the Worgen", description = "King Greymane, my father, has fallen ill! Every day he's worse, losing control over his mind, becoming... feral. He's bedridden in Stormwind as we speak, and he isn't the only one.\n\nKrennan Aranas found what he thought might be the cure in Outland, but it was corrupted beyond recognition. I need to find the cure before he loses every bit of his humanity!\n\nHemma, one of my guards, is sick as well. I need you to collect some soothpetal flowers and frog eyes. We have to try something.", objectives = "Obtain 6 Soothpetal Flowers and 8 Frog Eyes and bring them to Tess Greymane in Twilight Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33843] = { id = 33843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Broodmother Reeg'ak", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent." }
quests[33844] = { id = 33844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pale Hunter", description = "Spiders!\n\nWhere is my father!\n\nI feel so... so... good? Bad? Don't judge me! Leave me alone! I'm sleeping... in my brain.\n\nAHH!! More bunnies!\n\n<The dwarves eyes are extremely dilated. She appears to be hallucinating. >", sourceObjective = "Help Helga reclaim her sanity.", sourceObjectiveStatus = "unverified-source-field" }
quests[33846] = { id = 33846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flag: Seen Thrall Cyclone" }
quests[33847] = { id = 33847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flag: Seen Ga'nar Rolling Out" }
quests[33866] = { id = 33866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Veema's Herb Bag" }
quests[33867] = { id = 33867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Star-Reader's Box" }
quests[33868] = { id = 33868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Home of the Frostwolves", description = "You have arrived in Frostfire Ridge. Farseer Drek'Thar can guide you from here.", completion = "<The shaman grins at the harsh, windblown shore.>\n\nWelcome to the home of my people, {name}.", objectives = "Speak with Drek'Thar at the crash site in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33869] = { id = 33869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Elekk Horn" }
quests[33871] = { id = 33871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far south of here, and fulfill your destiny.", completion = "I am Seer Malune, the great keeper of memories. It is an honor to finally meet you.", objectives = "Speak to Seer Malune on Duskfall Island in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33872] = { id = 33872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust of the Dead", description = "I thought if I could just bring him here that I might be able to correct his transgression against the Light. That perhaps I could save my son! Now my beloved Arumel is a twisted phantasm.\n\nI'm left with no choice but to right my wrongs and I need your help.\n\nBring me duskwing dust from the moths on Duskfall Island. With your aid I can craft an elixir that will let us travel to the realm of the dead and lay Arumel to rest.", progress = "Do you have enough dust?", completion = "Thank you, {name}. With this dust and Aruunem berries I will craft the draught of the dead.", objectives = "Collect 7 Handfuls of Duskwing Dust from the Duskwing Moths on Duskfall Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33873] = { id = 33873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cure of Aruunem", description = "I need your help in creating an elixir that will allow us passage into the realm of the dead.\n\nIn order to create it I require a sampling of the local vegetation. You will find Aruunem berries scattered about on the island. Bring me as many as you can carry.\n\nBe warned, {name}: do not eat them raw! The poison in the berries would kill you within minutes!", progress = "Have you collected enough Aruunem berries?", completion = "I'm glad you did not eat any berries. I'm not sure what I would do if you were to die.", objectives = "Collect 60 Aruunem Berries from around Duskfall Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33874] = { id = 33874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aruumel's Rest", description = "It is my job to see what others cannot. I keep the memories and read them for others, but I can no longer do so because of my son.\n\nMy son turned his back on the light. When he perished I could not stand the thought that his spirit might not be welcomed into Auchindoun.\n\nI interfered and trapped him here. Now he twists and tortures the memories until they cannot be read.\n\nYou must do what I cannot bear to do myself. Use this elixir to enter the spirit realm...\n\n...and destroy my son's spirit.", progress = "Is it done?", completion = "Some memories are better left forgotten. Thank you, {name}.\n\nI will return you to our world.", objectives = "Enter the Spirit Realm and destroy the Memory of Arumel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33875] = { id = 33875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren, Goren, Gone!", description = "It's uncommon to see goren in Talador. We need to get a handle on this situation before it spreads and we lose all of our precious gems.\n\nThe only answer is to dispose of the creatures, and quickly!\n\nIt is imperative that you kill the leader too! If you don't they will just continue to come back.", objectives = "Destroy 15 Goren Stonechewers and their leader, Pastrok within the Jorune Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33878] = { id = 33878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Miner Left Behind", description = "In all of my years working the quarry I have never seen goren in this number. They came on so quickly, we had no time to react.\n\nNow the quarry has been weakened from their tunneling and eating. it's only a matter of time before the whole thing collapses.\n\nI refuse to leave anyone to die in there with those things! Please help me, {race}. Save as many of my miners as you can.", objectives = "Rescue 8 Jorune Miners from within the Jorune Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33879] = { id = 33879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren, Goren, Gone!", description = "I was all set to take a little trip to the nearby quarry when all of the sudden a bunch of goren bust out of the ground and started wreaking havoc!\n\nIt would be a shame for all of those beautiful gems to be destroyed by those filthy creatures. All they do is eat them! Can you believe that?!\n\nBe a dear and dispose of them. Make sure you get rid of the leader or they will only come back.", objectives = "Destroy 15 Goren Stonechewers and their leader, Pastrok within the Jorune Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33881] = { id = 33881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Live With 'Em, Can't Learn Without 'Em", description = "The Draenei here are so in touch with the light. It's imperative that we learn as much as we can from them.\n\nWe must find a way to overcome their distrust in us...\n\nThe Jorune Quarry was attacked by goren leaving many helpless miners trapped within. The miners aren't fighters and would probably appreciate help from anywhere at this point.\n\nMaybe if you lend a hand in rescuing them, we may earn ourselves some goodwill.", objectives = "Rescue 8 Jorune Miners from within the Jorune Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33882] = { id = 33882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Peachicky", description = "That mean old Sher'khaan! He's always been a bully to these poor peachicks, but this is crossing the line!\n\nI was trying to move this poor clutch out of the way of the demons when he attacked! Now the peachicks are spread out all over and they're scared!\n\nPlease help me bring them all back!", completion = "Oh thank you! Now these little peachicks can be moved to safety.", objectives = "Rescue 7 Frightened Peachicks and return them to Caleb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33883] = { id = 33883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure #2" }
quests[33884] = { id = 33884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sher'KHAAAAAAANNNN!", description = "The tigers here have gotten out of control! They're everywhere and meaner than ever!\n\nSher'khaan is the worst of them! He's huge and mean! Maybe a brave adventurer like you could take care of Sher'khaan and the other tigers once and for all.", completion = "You're so brave! I could never have taken Sher'khaan out on my own!\n\nNow I only have to worry about the scary orcs, giant birds, hippos, big bird men, spiders, everything being on fire...\n\nYa'know maybe I shouldn't be out here all by myself...", objectives = "Kill 8 Sharpfang Stalkers and Destroy Sher'khaan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33885] = { id = 33885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Harbor Treasure" }
quests[33886] = { id = 33886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ronokk's Belongings" }
quests[33887] = { id = 33887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mini-War Machine A" }
quests[33888] = { id = 33888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mini-War Machine B" }
