quests[33903] = { id = 33903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Romuul & Yrel Leave for Teluuna" }
quests[33904] = { id = 33904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance of Power", description = "The Prophet needs to locate the arkonite crystals, but in order to do that, I'll need to fix the projection discs on that platform.\n\nSpeak to my assistants around the observatory and bring me an Optical Disc, a Conducting Crystal, and my wrench.", objectives = "Speak to Romuul's assistants to collect an Optical Disc, Conducting Crystal, and Romuul's Wrench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33905] = { id = 33905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Closing the Door", description = "The Shadowmoon orcs are using portals to bring in reinforcements and smuggle away draenei captives.\n\nIf we are to have any hope of retaking the village, we must destroy the portals at once.\n\nThe only way to do this is to kill the portalmasters who keep the rifts open.", progress = "Breaking the fabric of space is extremely costly magic. It must rend their very souls.", completion = "Wonderful. That should slow down the attack.\n\nOur forces should be able to retake the forest quickly.", objectives = "Close 3 Void Portals by killing Shadowmoon Portalmasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33906] = { id = 33906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Kangaroo!", description = "test" }
quests[33907] = { id = 33907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Shards", description = "I know what the Bonechewer are after.\n\nAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.\n\nThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.\n\nGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.", objectives = "Retrieve the Shard of Souls in the Tomb of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33908] = { id = 33908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Shards", description = "I know what the Bonechewer are after.\n\nAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.\n\nThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.\n\nGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.", objectives = "Retrieve the Shard of Souls in the Tomb of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33909] = { id = 33909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flag: Seen Ga'nar Rolling Out to Bladespire" }
quests[33910] = { id = 33910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aklana Rescue" }
quests[33911] = { id = 33911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Draenei Left Behind", description = "Yuuri, head caretaker of the outer terraces of Auchindoun, hasn't been accounted for yet.\n\nThe last time anyone saw him, he was heading into the Tomb of Souls to protect the key shard. Will you make sure he finds his way here safely?", sourceObjective = "Find Yuuri near the Tomb of Souls in the Court of Souls.", sourceObjectiveStatus = "unverified-source-field" }
quests[33913] = { id = 33913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Times", description = "This alliance between the Bonechewer and Teron'gore does not bode well.\n\nWe cannot allow the remaining two key fragments to fall into their hands. The Auchenai cannot stop the onslaught, so the duty falls on us.\n\nLet us waste no time. We ride for the Tomb of Lights at once.", objectives = "Ride to the Tomb of Lights with Lady Liadrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33914] = { id = 33914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut Guttra", description = "Guttra Wolfchew's hunger can be blamed for this massacre. He will pay with his life for the blood spilled today. \n\nYou can find Guttra up on Grimfrost Hill to the north. Slay him and return to me.\n\nWhen you get back we shall drink to our victory.", objectives = "Kill Guttra Wolfchew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33915] = { id = 33915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Young Hearts", description = "My nephew never pays attention to his surroundings. In his eagerness to prove himself, he has strayed from the pack -- again.\n\nHe reminds me of myself when I was a youngling.\n\nIf you see Orac, tell him to return home. We need to finish preparing for tomorrow's hunt.", completion = "Thank you, {name}. I'm sure Orac will think twice before he strays from the pack again.", objectives = "Find Orac and tell him to return home to his uncle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33916] = { id = 33916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Arena Master's Warhorn" }
quests[33917] = { id = 33917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Flow", description = "You there, we need to stop the flow of demon reinforcements!\n\nDo you see the floating fel crystals spread throughout the front? Those resonators are powering the portals unleashing hell on our forces. I need you to take them out!", progress = "We can't hold out forever!", completion = "We can take it from here. Light's blessings to you, {class}.", objectives = "Destroy 4 Burning Resonators in the Burning Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33918] = { id = 33918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Grondo's Bounty", description = "Grondo, a mad gronn, has been seen roaming the Crackling Plains.\n\nThis beast has been killing entire herds of clefthoof and devouring innocent frost wolves. We must destroy this threat before it reaches the Garrison.", completion = "Very good. We don't be needin' a gronn bearin' down on us before we get our defenses all established.", objectives = "Kill Grondo in the Crackling Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33919] = { id = 33919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gutsmash the Destroyer", description = "Gutsmash has proven to be more than a worthy adversary. Gather a small group together and end his reign of terror once and for all.", completion = "Gutsmash is dead? I'll drink to that. You're alright, {name}.", objectives = "Kill Gutsmash the Destroyer in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33920] = { id = 33920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of Auchindoun", description = "A band of Shadow Council orcs stole the Heart of Auchindoun!\n\nThe Heart powers all of Auchindoun's defenses. Thankfully we were able to save its core and one of its four pieces.\n\nThe warlock O'mogg Blackheart is using Karab'uun, one of the stolen pieces, to power the largest portal in the Burning Front. Return Karab'uun to me.", progress = "I trust you have Karab'uun. I am not known for my patience when the countless souls inside Auchindoun are in danger.", completion = "<Soulbinder Nyami's lips curl into a smile.>\n\nWell done. Only two pieces remain. I've already dispatched my soulbinders to track them down.", objectives = "Defeat O'mogg Blackheart and retrieve Karab'uun in the Burning Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33921] = { id = 33921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Axes", description = "The saberon usually keep to themselves, but sometimes they range out of their dens and attack.\n\nA pride of them live in the Windswept Lowland and have been coming too close for comfort, especially at night.\n\nThey even attacked a shipment of axes and took them back to their den!", objectives = "Recover 8 Stolen Frostwolf Axes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33923] = { id = 33923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons? In Auchindoun?", description = "Demons! I feared as much.\n\nWe cannot let them leave that tomb. They musn't be allowed near Auchindoun!\n\nQuickly, go in and shut down the portal letting them in while I help rally the Auchenai's defenses. There must be a powerful warlock keeping it open. Kill him and the portal will fall apart!", objectives = "Kill O'mogg Blackheart in the Tomb of Lights to shut down the demon portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33924] = { id = 33924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saberon Matriarch", description = "The current matriarch of the Windswept Lowland saberon pride is bold.\n\nShe leads her pride in ambushes and attacks that some consider organized raids on our supply lines.\n\nThe intelligence she displays  is becoming a legitimate threat.\n\nTake her out and perhaps she'll be replaced with a less dangerous leader.", objectives = "Slay the Saberon Pridematron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33925] = { id = 33925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 01" }
quests[33926] = { id = 33926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Lagoon Pool" }
quests[33927] = { id = 33927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenei Camp Explosion Tracker" }
quests[33928] = { id = 33928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wrong of Earth and Fire", description = "The molten core appears to be the mutated remains of an elemental that consisted of both earth and fire.\n\nSlag elementals should not exist upon the plateau where the elements live in purity.\n\nYou decide that the core should be taken to Incineratus at the Throne of Elements for examination.\n\nPerhaps the great fury of fire will know what to make of this core and your battle with Magmire.", completion = "<Incineratus examines the core as you explain the circumstances behind its acquisition>\n\nIndeed, slag elementals should not exist upon the plateau. The plateau has grown unstable, causing the elemental spirits there to devolve and mutate.\n\nSo long as an earthen fury is absent from the throne, the imbalance in the elements will worsen.\n\nGordawg must return to the Throne of Elements if balance is to be maintained.", objectives = "Deliver the Molten Core to Incineratus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33929] = { id = 33929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shivertail's Den", description = "The Frostwolf pup looks at you with his big eyes. He howls and stares into the cave.\n\nIt's unusual for a wolf this young to be wandering around by itself. Shivertail's parents must be nearby.", progress = "Shivertail smells your boots.", completion = "Shivertail snuggles up to his mother. He is clearly happy to be reunited with most of his pack.", objectives = "Search for Shivertail's parents in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33930] = { id = 33930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Saberon Stash" }
quests[33931] = { id = 33931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Not a Quest", description = "We need help! But not from you...", completion = "Haha!", objectives = "Help Deceptia", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33933] = { id = 33933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Deceptia's Smoldering Boots" }
