quests[33952] = { id = 33952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunting Party", description = "Korga and her brothers have been out hunting for days and have not returned.\n\nThis is a common problem amongst our clan.\n\nCall them in so they can get some proper rest.", sourceObjective = "Find the Frostwolf Hunters in the Windswept Lowland.", sourceObjectiveStatus = "unverified-source-field" }
